import pandas as pd
column_query = """
SELECT column_name 
FROM information_schema.columns 
WHERE table_name = 'enterprise_data'
"""
columns_info = execute_sql_query(column_query)
all_columns = columns_info['column_name'].tolist()
cv_edu_cols = [col for col in all_columns if 'CV Employee Education' in col and 'CV Degree Name' in col]
if not cv_edu_cols:
    result = {'type': 'string', 'value': 'No CV Employee Education columns with CV Degree Name found in the dataset.'}
else:
    cv_edu_col = cv_edu_cols[0]
    employee_query = """
    SELECT 
        "[Employee Master[Employee Name]]",
        "[Employee Master[Degree]]"
    FROM enterprise_data
    WHERE "[Employee Master[Degree]]" IS NOT NULL
    """
    df_employee = execute_sql_query(employee_query)
    cv_query = f"""
    SELECT 
        "[Employee Master[Employee Name]]",
        cv_rec['CV Degree Name'] AS cv_degree_name
    FROM enterprise_data, UNNEST("{cv_edu_col}") AS t(cv_rec)
    WHERE cv_rec['CV Degree Name'] IS NOT NULL
    """
    df_cv = execute_sql_query(cv_query)
    results = []
    for idx, emp in df_employee.iterrows():
        emp_name = emp['[Employee Master[Employee Name]]']
        master_degree = emp['[Employee Master[Degree]]']
        cv_degrees = df_cv[df_cv['[Employee Master[Employee Name]]'] == emp_name]['cv_degree_name'].tolist()
        if not cv_degrees:
            results.append(f"""Employee: {emp_name}
  Employee Master Degree: {master_degree}
  CV Degree Names: None recorded
  Difference: No CV education data available""")
        else:
            cv_degree_str = ', '.join(set(cv_degrees))
            if master_degree in cv_degrees:
                results.append(f"""Employee: {emp_name}
  Employee Master Degree: {master_degree}
  CV Degree Names: {cv_degree_str}
  Difference: Master degree matches CV record(s)""")
            else:
                results.append(f"""Employee: {emp_name}
  Employee Master Degree: {master_degree}
  CV Degree Names: {cv_degree_str}
  Difference: Master degree does NOT match any CV record""")
    result = {'type': 'string', 'value': '\n\n'.join(results)}
result = result
